window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-135"]=[{"id":"set2-6rciEGFo","fingerprint":"f26475c1eff0a7a6","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este rata ideală de injectare a soluției anestezice pentru a preveni distensia bruscă a țesuturilor moi?","options":[{"id":"A","text":"0.5 ml/min"},{"id":"B","text":"Nu există o rată ideală specificată"},{"id":"C","text":"2 ml/min"},{"id":"D","text":"3 ml/min"},{"id":"E","text":"1 ml/min"}],"correct":["E"],"pages":[560],"source":"set-2"},{"id":"set2-2mWf4v17","fingerprint":"55df476ec9b21739","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele reprezintă cauze posibile ale durerii la injectarea soluției anestezice?","options":[{"id":"A","text":"Tamponarea soluției anestezice cu bicarbonat de sodiu."},{"id":"B","text":"Injectarea lentă a soluției, la o rată de 1 ml/min."},{"id":"C","text":"Injectarea unei soluții anestezice cu vasoconstrictor, care are un pH de 3-3,5."},{"id":"D","text":"Utilizarea unei soluții anestezice cu un pH în jur de 5."},{"id":"E","text":"Folosirea unui ac nou, steril, pentru fiecare puncție."}],"correct":["C","D"],"pages":[560],"source":"set-2"},{"id":"set2-W9C7K79O","fingerprint":"5997808603d81a32","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce simptom caracteristic acuză un pacient în momentul înțepării unui trunchi nervos în timpul unei puncții anestezice?","options":[{"id":"A","text":"O durere surdă care se instalează lent și persistă."},{"id":"B","text":"O amorțeală rapidă în teritoriul respectiv, fără nicio senzație dureroasă."},{"id":"C","text":"O senzație de presiune intensă, fără durere."},{"id":"D","text":"O senzație de arsură la locul puncției."},{"id":"E","text":"O durere fulgurantă, locală sau iradiată în teritoriul nervului."}],"correct":["E"],"pages":[560],"source":"set-2"},{"id":"set2-OCXAIBLK","fingerprint":"903b841e5cd20841","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt consecințele posibile ale înțepării unui trunchi nervos în timpul anesteziei?","options":[{"id":"A","text":"Accidentul poate provoca procese de nevrită traumatică."},{"id":"B","text":"Efectul anestezic este diminuat și de scurtă durată."},{"id":"C","text":"Durerea fulgurantă inițială persistă pe toată durata efectului anestezic."},{"id":"D","text":"Anestezia se instalează foarte rapid."},{"id":"E","text":"Durata anesteziei poate fi prelungită la 5-6 ore."}],"correct":["A","D","E"],"pages":[560],"source":"set-2"},{"id":"set2-9u7TZ0qe","fingerprint":"67870dd424469b2b","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"În ce zone anatomice este mai probabil ca injectarea cu presiune a anestezicului să provoace dureri vii prin distensia bruscă a țesuturilor?","options":[{"id":"A","text":"În periost."},{"id":"B","text":"În țesutul muscular lax al obrazului."},{"id":"C","text":"În țesutul conjunctiv lax al planșeului bucal."},{"id":"D","text":"În fibromucoasa palatină."},{"id":"E","text":"În gingivomucoasa alveolară fixă."}],"correct":["A","D","E"],"pages":[560],"source":"set-2"},{"id":"set2-s8kYOZFB","fingerprint":"3f7382b79c834be6","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este pH-ul specificat pentru soluțiile anestezice care conțin vasoconstrictor?","options":[{"id":"A","text":"În jur de 5"},{"id":"B","text":"În jur de 7"},{"id":"C","text":"Peste 8"},{"id":"D","text":"Nu există o diferență de pH între soluțiile cu și fără vasoconstrictor."},{"id":"E","text":"În jur de 3-3,5"}],"correct":["E"],"pages":[560],"source":"set-2"},{"id":"set2-XBRAG3LS","fingerprint":"715560eae8a7eec2","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"În cadrul căror tehnici de anestezie este mai frecvent accidentul de înțepare a trunchiului nervos, în special când acesta se găsește într-un canal osos?","options":[{"id":"A","text":"Anestezia plexală supraperiostală."},{"id":"B","text":"Anestezia nervului incisiv."},{"id":"C","text":"Anestezia nervului palatin."},{"id":"D","text":"Anestezia nervului infraorbitar."},{"id":"E","text":"Anestezia intraligamentară."}],"correct":["B","C","D"],"pages":[560],"source":"set-2"},{"id":"set2-P5yP02hn","fingerprint":"5d828d34b7bc6775","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele reprezintă consecințe posibile ale utilizării soluțiilor anestezice contaminate?","options":[{"id":"A","text":"Parestezie tranzitorie"},{"id":"B","text":"Edem postanestezic"},{"id":"C","text":"Trismus"},{"id":"D","text":"Extravazare sanguină în spațiul extracelular"},{"id":"E","text":"Dispariția rapidă a durerii odată cu instalarea anesteziei"}],"correct":["A","B","C"],"pages":[561],"source":"set-2"},{"id":"set2-Ekr8T7ci","fingerprint":"55ff08af2575b549","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce caracterizează senzația dureroasă la injectarea unui anestezic local, atunci când aceasta este cauzată de pH-ul soluției?","options":[{"id":"A","text":"Conduce frecvent la apariția edemului postanestezic."},{"id":"B","text":"Este tranzitorie și dispare pe măsură ce se instalează anestezia."},{"id":"C","text":"Este însoțită de o mare probabilitate de apariție a leziunilor tisulare."},{"id":"D","text":"Lasă în urmă o sensibilitate reziduală după dispariția anesteziei."},{"id":"E","text":"Se datorează difuziei soluțiilor de sterilizare în interiorul carpulei."}],"correct":["B"],"pages":[561],"source":"set-2"},{"id":"set2-lf_Ms6JH","fingerprint":"fea9516adad8463b","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care sunt efectele acidității crescute din țesuturile inflamate asupra acțiunii anestezicului local?","options":[{"id":"A","text":"Determină instalarea rapidă a anesteziei, dar cu o durată redusă."},{"id":"B","text":"Favorizează formarea formei cationice în interiorul fibrei nervoase."},{"id":"C","text":"Limitează formarea bazei neionizate necesară difuziei în nerv."},{"id":"D","text":"Scade conductibilitatea nervoasă prin creșterea pragului de răspuns."},{"id":"E","text":"Determină o absorbție mai lentă a anestezicului în circulația sanguină."}],"correct":["C"],"pages":[561],"source":"set-2"},{"id":"set2-IIaOkU3G","fingerprint":"a81c64c1eaf5c5ad","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"În contextul mecanismului de acțiune al anestezicelor locale, care este rolul specific al formei cationice a moleculei de anestezic?","options":[{"id":"A","text":"Crește conductibilitatea nervoasă în țesuturile inflamate."},{"id":"B","text":"Este neutralizată de sistemele tampon din fluidul tisular."},{"id":"C","text":"Blochează canalele de sodiu din interiorul fibrei nervoase."},{"id":"D","text":"Difuzează prin teaca nervoasă pentru a ajunge la locul de acțiune."},{"id":"E","text":"Este responsabilă pentru solubilitatea și stabilitatea soluției în carpulă."}],"correct":["C"],"pages":[561],"source":"set-2"},{"id":"set2-7zo_M0-4","fingerprint":"f0ed3db31650772d","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este o metodă recomandată pentru obținerea anesteziei în prezența unei inflamații tisulare?","options":[{"id":"A","text":"Injectarea soluției anestezice direct în vasele de sânge dilatate pentru o difuzie mai rapidă."},{"id":"B","text":"Aplicarea de comprese reci pentru a reduce pH-ul local înainte de injectare."},{"id":"C","text":"Injectarea unei cantități mai mici de anestezic direct în zona inflamată pentru a minimiza distensia tisulară."},{"id":"D","text":"Administrarea anestezicului local la distanță de zona de inflamație, preferabil printr-o anestezie tronculară periferică."},{"id":"E","text":"Utilizarea exclusivă a carpulelor depozitate în soluții de alcool pentru a asigura sterilitatea în focarul infecțios."}],"correct":["D"],"pages":[561],"source":"set-2"},{"id":"set2-w1jRyJfZ","fingerprint":"f09bb2c6f2986250","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce măsură imediată se recomandă în cazul perforării accidentale a unui vas de sânge superficial în timpul injectării anestezicului local, urmată de sângerare la locul puncției?","options":[{"id":"A","text":"Abandonarea imediată a procedurii și reevaluare după 24 de ore."},{"id":"B","text":"Aplicarea de căldură locală pentru a stimula coagularea."},{"id":"C","text":"Aspirarea sângelui extravazat pentru a preveni formarea hematomului."},{"id":"D","text":"Injectarea unei cantități suplimentare de anestezic pentru vasoconstricție."},{"id":"E","text":"Compresie locală timp de 1-2 minute."}],"correct":["E"],"pages":[561],"source":"set-2"},{"id":"set2-05c0myrX","fingerprint":"592afadee1c1478d","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este motivul pentru care nu se recomandă injectarea soluțiilor anestezice direct în zonele de inflamație sau infecție?","options":[{"id":"A","text":"Injectarea este nedureroasă, mascând astfel extinderea infecției."},{"id":"B","text":"Provoacă întotdeauna leziuni tisulare permanente și parestezie."},{"id":"C","text":"Determină o vasoconstricție puternică, limitând efectul anestezicului."},{"id":"D","text":"Anestezicul este complet inactivat de exudatul inflamator."},{"id":"E","text":"Există riscul de a extinde infecția în zonele neinteresate."}],"correct":["E"],"pages":[561],"source":"set-2"},{"id":"set2-7pSj4ssb","fingerprint":"636670d5a4db2c3a","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce acțiune este recomandată în cazul în care, în timpul unei anestezii tronculare periferice, se aspiră o cantitate mare de sânge care se amestecă cu soluția anestezică?","options":[{"id":"A","text":"Se schimbă atât seringa, cât și soluția anestezică înainte de a relua procedura."},{"id":"B","text":"Se întrerupe procedura și se reprogramează pentru o altă zi."},{"id":"C","text":"Se retrage ușor acul, se reaspiră și, dacă nu mai apare sânge, se injectează soluția."},{"id":"D","text":"Se injectează soluția, dar se monitorizează pacientul pentru semne de supradozaj."},{"id":"E","text":"Se continuă injectarea lentă a soluției pentru a minimiza riscurile sistemice."}],"correct":["A"],"pages":[562],"source":"set-2"},{"id":"set2-XhmDd-1z","fingerprint":"4e161e7035a989a3","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt consecințele posibile ale unei injectări accidentale intravasculare a unei soluții de anestezic local?","options":[{"id":"A","text":"Scăderea bruscă a concentrației sanguine a anestezicului."},{"id":"B","text":"O anestezie de lungă durată și foarte profundă în teritoriul vizat."},{"id":"C","text":"Apariția unor reacții acute de supradozare."},{"id":"D","text":"Riscul unor accidente generale."},{"id":"E","text":"Absența anesteziei în zona de intervenție."}],"correct":["C","D","E"],"pages":[562],"source":"set-2"},{"id":"set2-IXP8CYNM","fingerprint":"d3e7297a7f3a5da0","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care dintre următoarele afirmații referitoare la hematomul post-anestezic este corectă?","options":[{"id":"A","text":"În anestezia nervului mentonier, riscul de hematom este foarte ridicat, deoarece acul pătrunde frecvent în canal."},{"id":"B","text":"Densitatea țesuturilor ce înconjoară vasul lezat nu influențează apariția hematomului."},{"id":"C","text":"Apare frecvent după o anestezie în bolta palatină, datorită densității scăzute a țesuturilor."},{"id":"D","text":"Extravazarea sanguină se oprește atunci când presiunea extravasculară o depășește pe cea intravasculară sau la formarea cheagului."},{"id":"E","text":"Incidența sa este mai mare după anestezia la spina Spix decât după anestezia la tuberozitate."}],"correct":["D"],"pages":[562],"source":"set-2"},{"id":"set2-K4SeaThu","fingerprint":"c27b4c911775ff57","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Lezarea căror structuri vasculare poate duce la formarea unui hematom al obrazului în timpul anesteziei la tuberozitate?","options":[{"id":"A","text":"Venei retromandibulare."},{"id":"B","text":"Plexului venos pterigoidian."},{"id":"C","text":"Arterei alveolare postero-superioare."},{"id":"D","text":"Arterei faciale."},{"id":"E","text":"Arterei maxilare interne."}],"correct":["B","C","E"],"pages":[562],"source":"set-2"},{"id":"set2-mKclmp59","fingerprint":"d107cdd5eeacfdeb","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Ce măsuri terapeutice sunt indicate în managementul unui hematom al obrazului apărut imediat după o anestezie la tuberozitate?","options":[{"id":"A","text":"Aplicarea unui prișnitz rece, menținut printr-un pansament compresiv, pentru 24-48 de ore."},{"id":"B","text":"Aplicarea imediată a unui prișnitz cald pentru a accelera resorbția."},{"id":"C","text":"Efectuarea unui masaj viguros al regiunii pentru a dispersa colecția sanguină."},{"id":"D","text":"Introducerea unui rulou de comprese în șanțul vestibular superior, cât mai distal posibil."},{"id":"E","text":"Evitarea expunerii la căldură a zonei pentru cel puțin șase ore."}],"correct":["A","D","E"],"pages":[562],"source":"set-2"},{"id":"set2-PgLEodoU","fingerprint":"5a1ea65481b210ee","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care sunt manifestările clinice caracteristice ale unui hematom apărut după anestezia la spina Spix?","options":[{"id":"A","text":"O colecție sanguină în bolta palatină, vizibilă imediat după injectare."},{"id":"B","text":"Apariția echimozelor în regiunea submandibulară după 24 de ore."},{"id":"C","text":"O tumefacție geniană extinsă anterior și inferior."},{"id":"D","text":"Exoftalmie și asimetrie facială."},{"id":"E","text":"Tumefacție pe fața internă a ramului mandibular și posibilă modificare de culoare a mucoasei."}],"correct":["E"],"pages":[562],"source":"set-2"},{"id":"set2-pYcAObte","fingerprint":"f235cfb4106d3eab","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce eroare tehnică în timpul anesteziei la spina Spix poate duce la pareza facială tranzitorie?","options":[{"id":"A","text":"Lezarea arterei maxilare interne cu acul."},{"id":"B","text":"Injectarea soluției anestezice prea rapid."},{"id":"C","text":"Injectarea intravasculară a unei cantități mici de anestezic."},{"id":"D","text":"Utilizarea unei soluții anestezice fără vasoconstrictor."},{"id":"E","text":"Injectarea prea profund, cu acul direcționat posterior, în glanda parotidă."}],"correct":["E"],"pages":[562],"source":"set-2"},{"id":"set2-eckgEzcD","fingerprint":"d36b2113957a7def","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care dintre următoarele semne clinice NU este caracteristic parezei faciale tranzitorii post-anestezice?","options":[{"id":"A","text":"Exoftalmia."},{"id":"B","text":"Coborârea comisurii bucale."},{"id":"C","text":"Tumefacția pe fața internă a ramului mandibular."},{"id":"D","text":"Dispariția mișcărilor mimicii de partea afectată."},{"id":"E","text":"Asimetria facială."}],"correct":["C"],"pages":[562],"source":"set-2"},{"id":"set2-J-GMXWwT","fingerprint":"46e39827983d035b","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este mecanismul principal de producere a parezei faciale tranzitorii în timpul anesteziei la spina Spix?","options":[{"id":"A","text":"Înțeparea ligamentului pterigomandibular și tensionarea acestuia."},{"id":"B","text":"Realizarea unei ischemii tranzitorii la nivelul nervului facial."},{"id":"C","text":"Introducerea acului mult mai sus, cu infiltrarea nervului auriculo-temporal."},{"id":"D","text":"Difuzarea anestezicului în orbită și infiltrarea nervului optic."},{"id":"E","text":"Injectarea substanței anestezice prea profund și posterior, în glanda parotidă."}],"correct":["E"],"pages":[563],"source":"set-2"},{"id":"set2-zGN4EWU-","fingerprint":"2e9a08c8589647d7","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele semne clinice sunt caracteristice parezei faciale tranzitorii post-anestezice?","options":[{"id":"A","text":"Diplopia"},{"id":"B","text":"Anestezia regiunii temporale"},{"id":"C","text":"Coborârea comisurii bucale de partea afectată"},{"id":"D","text":"Dispariția mișcărilor mimicii de partea afectată"},{"id":"E","text":"Exoftalmia"}],"correct":["C","D","E"],"pages":[563],"source":"set-2"},{"id":"set2-UpVeVEZ6","fingerprint":"1e74d996d0b21229","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce factor poate determina o durată mai mare a tulburărilor motorii în cazul unei pareze faciale tranzitorii?","options":[{"id":"A","text":"Vecinătatea nervului facial față de locul injectării"},{"id":"B","text":"Prezența vasoconstrictorului în soluția anestezică"},{"id":"C","text":"Utilizarea unui ac de unică folosință"},{"id":"D","text":"Injectarea rapidă a anestezicului"},{"id":"E","text":"Volumul mare de substanță anestezică injectată"}],"correct":["B"],"pages":[563],"source":"set-2"},{"id":"set2-YPL-KI51","fingerprint":"c0f5d3ede585ec6e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este consecința infiltrării accidentale a nervului auriculo-temporal în cursul anesteziei la spina Spix?","options":[{"id":"A","text":"O anestezie a regiunii temporale și a pavilionului urechii."},{"id":"B","text":"Pareza tranzitorie a musculaturii mimicii."},{"id":"C","text":"Diplopie și pierderea temporară a vederii."},{"id":"D","text":"Trismus persistent prin contracția mușchiului pterigoidian intern."},{"id":"E","text":"Hemoragii intraorbitare sau intraoculare."}],"correct":["A"],"pages":[563],"source":"set-2"},{"id":"set2-4jHWCiRs","fingerprint":"415b20d4c83069ca","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele tulburări oculare pot apărea prin difuzarea anestezicului în orbită în timpul anesteziei nervului infraorbitar?","options":[{"id":"A","text":"Diplopie"},{"id":"B","text":"Echimoze conjunctivo-bulbare"},{"id":"C","text":"Oftalmoplegie"},{"id":"D","text":"Trismus persistent"},{"id":"E","text":"Pierderea temporară a vederii"}],"correct":["A","C","E"],"pages":[563],"source":"set-2"},{"id":"set2-1N3eXXil","fingerprint":"850a12de4073432d","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Pentru a evita accidentele oculare în timpul anesteziei la orificiul infraorbitar, care este adâncimea maximă de pătrundere recomandată în canal?","options":[{"id":"A","text":"5-8 mm"},{"id":"B","text":"1-2 mm"},{"id":"C","text":"Până la ambou"},{"id":"D","text":"0,5-0,8 mm"},{"id":"E","text":"Până la contactul ferm cu periostul"}],"correct":["D"],"pages":[563],"source":"set-2"},{"id":"set2--0sh3EkS","fingerprint":"84b9800df68c2fb5","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este principala cauză a ruperii acului în timpul anesteziilor tronculare periferice?","options":[{"id":"A","text":"O mișcare bruscă, imprevizibilă a pacientului."},{"id":"B","text":"Injectarea rapidă a anestezicului."},{"id":"C","text":"Utilizarea unor ace subțiri cu defecte de fabricație."},{"id":"D","text":"Schimbarea bruscă a direcției acului intratisular."},{"id":"E","text":"Introducerea completă a acului până la ambou."}],"correct":["A"],"pages":[563],"source":"set-2"},{"id":"set2-legitIZE","fingerprint":"32fcc946d0ff2963","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Ce factori favorizanți sunt incriminați în producerea ruperii acului de anestezie?","options":[{"id":"A","text":"Protejarea globului ocular cu degetele mâinii stângi."},{"id":"B","text":"Menținerea permanentă a acului în contact cu planul osos."},{"id":"C","text":"Utilizarea unor ace care au fost îndoite anterior."},{"id":"D","text":"Introducerea completă a acului până la ambou."},{"id":"E","text":"Injectarea rapidă a anestezicului care provoacă contracția mușchiului pterigoidian intern."}],"correct":["C","D","E"],"pages":[563],"source":"set-2"},{"id":"set2-gk5VX6Cx","fingerprint":"b9a49aa5a5e7c05b","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este atitudinea corectă imediat după ruperea unui ac de anestezie, dacă fragmentul nu este vizibil în cavitatea orală?","options":[{"id":"A","text":"Se încearcă prinderea capătului rupt cu o pensă Pean."},{"id":"B","text":"Se administrează un antibiotic pentru a preveni infecția."},{"id":"C","text":"Se solicită pacientului să efectueze mișcări de închidere și deschidere a gurii pentru a exterioriza acul."},{"id":"D","text":"Se solicită pacientului să mențină gura deschisă și se evită orice manoperă până la localizarea radiologică."},{"id":"E","text":"Se amână intervenția chirurgicală pentru câteva zile pentru a permite stabilizarea fragmentului."}],"correct":["D"],"pages":[563],"source":"set-2"},{"id":"set2-lWaOuUn2","fingerprint":"3b21fc777d1adb49","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt cauzele incriminate în etiologia ulcerației mucoasei care poate apărea postanestezic?","options":[{"id":"A","text":"Herpesul simplex"},{"id":"B","text":"Puncțiile septice"},{"id":"C","text":"Traumatismele tisulare"},{"id":"D","text":"Ischemia prelungită a țesuturilor"},{"id":"E","text":"Stomatita aftoasă recidivantă"}],"correct":["A","C","E"],"pages":[564],"source":"set-2"},{"id":"set2-cMfRZGEx","fingerprint":"01c2e1aa92dbe940","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce caracteristică diferențiază manifestarea orală a herpesului simplex de cea a stomatitei aftoase recidivante în contextul complicațiilor postanestezice?","options":[{"id":"A","text":"Nu poate fi activată de traumatismele tisulare."},{"id":"B","text":"Ulcerațiile persistă mai mult de 14 zile."},{"id":"C","text":"Se manifestă inițial ca mici vezicule pe mucoasa fixă."},{"id":"D","text":"Este considerată a fi, cel mai frecvent, un proces autoimun."},{"id":"E","text":"Apare frecvent în vestibulul bucal, la nivelul mucoasei mobile."}],"correct":["C"],"pages":[564],"source":"set-2"},{"id":"set2-xPpI9Ry2","fingerprint":"6964d0a8405a7ac9","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"În tratamentul simptomatic al ulcerațiilor postanestezice, ce clasă de medicamente nu este recomandată din cauza riscului crescut de suprainfectare?","options":[{"id":"A","text":"Analgezicele locale"},{"id":"B","text":"Antihistaminicele"},{"id":"C","text":"Antiinflamatoarele"},{"id":"D","text":"Antialgicele administrate sistemic"},{"id":"E","text":"Corticosteroizii"}],"correct":["E"],"pages":[564],"source":"set-2"},{"id":"set2-Lgi1unM_","fingerprint":"ace9f5e2dfae207d","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect necroza mucoasei ca o complicație postanestezică?","options":[{"id":"A","text":"Suprainfectarea leziunii este o complicație foarte frecventă."},{"id":"B","text":"Vindecarea completă are loc în 3-5 zile, fără sechele."},{"id":"C","text":"Ischemia prelungită care o cauzează se datorează în principal vasoconstrictorului din soluția anestezică."},{"id":"D","text":"Este mai frecventă în mucoasa extensibilă a vestibulului bucal."},{"id":"E","text":"Zona de necroză are inițial o colorație violacee, apoi devine brun-cenușie."}],"correct":["C","E"],"pages":[564],"source":"set-2"},{"id":"set2-JXHS5Ouj","fingerprint":"84a21aa6f7a26638","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este atitudinea terapeutică corectă în cazul unei necroze a mucoasei palatine postanestezice?","options":[{"id":"A","text":"Aplicarea de meșe iodoformate menținute cu o placă palatinală acrilică."},{"id":"B","text":"Administrarea de antibiotice cu spectru larg pentru a preveni suprainfectarea."},{"id":"C","text":"Administrarea de corticosteroizi pentru a reduce reacția inflamatorie locală."},{"id":"D","text":"Chiuretarea agresivă a osului subiacent pentru a stimula vindecarea."},{"id":"E","text":"Evitarea oricărei intervenții locale, permițând vindecarea spontană."}],"correct":["A"],"pages":[564],"source":"set-2"},{"id":"set2-jGsl0NUg","fingerprint":"adf0d7314ca961a0","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Prin ce mecanism se produc cel mai frecvent injectitele postanestezice?","options":[{"id":"A","text":"Reactivarea unei infecții virale latente, precum herpesul simplex."},{"id":"B","text":"O reacție autoimună la componentele soluției anestezice."},{"id":"C","text":"Decolarea brutală a mucoperiostului în timpul manevrelor chirurgicale."},{"id":"D","text":"Ischemia tisulară indusă de vasoconstrictor, care favorizează necroza."},{"id":"E","text":"Puncțiile septice, datorate contaminării acului sau asepsiei incorecte."}],"correct":["E"],"pages":[564],"source":"set-2"},{"id":"set2-TMEJOukS","fingerprint":"715e0f68a817e491","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce factori locali favorizează dezvoltarea unui proces septic în spațiile fasciale după o puncție anestezică?","options":[{"id":"A","text":"Utilizarea unei soluții anestezice fără vasoconstrictor."},{"id":"B","text":"Absența unui răspuns inflamator local imediat."},{"id":"C","text":"O vascularizație bogată care accelerează răspunsul imun."},{"id":"D","text":"Prezența mucoasei fixe și keratinizate, care limitează diseminarea."},{"id":"E","text":"Prezența abundentă a țesutului celulo-adipos și a hematoamelor."}],"correct":["E"],"pages":[564],"source":"set-2"},{"id":"set2-XoGX-yR3","fingerprint":"c71507ea2c903bf4","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt manifestările clinice caracteristice unei infecții postanestezice dezvoltate în spațiile fasciale oro-maxilo-faciale?","options":[{"id":"A","text":"Dureri nevralgiforme care cedează la antialgicele uzuale"},{"id":"B","text":"Tumefacție"},{"id":"C","text":"Apariția unor ulcerații cu margini regulate pe mucoasa fixă"},{"id":"D","text":"Trismus"},{"id":"E","text":"Disfagie"}],"correct":["B","D","E"],"pages":[564],"source":"set-2"},{"id":"set2-GBwdiLAh","fingerprint":"a38292a2a8919f54","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt simptomele caracteristice unui proces supurativ postanestezic cu localizare în spațiile profunde?","options":[{"id":"A","text":"Apariția simptomatologiei în primele 24 de ore de la puncția anestezică."},{"id":"B","text":"Tratament de primă intenție bazat exclusiv pe antibioterapie."},{"id":"C","text":"Dureri nevralgiforme iradiate care cedează la antialgicele obișnuite."},{"id":"D","text":"Tumefacție, trismus și disfagie."},{"id":"E","text":"Dureri nevralgiforme iradiate care nu răspund la analgezice comune."}],"correct":["D","E"],"pages":[565],"source":"set-2"},{"id":"set2-B9GasVv3","fingerprint":"a346ff1fe9b64599","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următorii factori sunt implicați în etiologia trismusului persistent postanestezic?","options":[{"id":"A","text":"Ischemia prelungită a țesuturilor musculare cauzată de vasoconstrictorul din soluția anestezică."},{"id":"B","text":"O puncție anestezică unică, efectuată lent și atraumatic."},{"id":"C","text":"O hemoragie redusă cantitativ, care este rapid absorbită de țesuturi."},{"id":"D","text":"Puncția septică ce duce la însămânțarea spațiului pterigomandibular."},{"id":"E","text":"Depunerea unei cantități mari de anestezic local într-o zonă limitată, producând distensii tisulare."}],"correct":["A","D","E"],"pages":[565],"source":"set-2"},{"id":"set2--N3nRbM5","fingerprint":"f56aaf169c36033c","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Ce caracterizează evoluția clinică a trismusului postanestezic în faza acută?","options":[{"id":"A","text":"Simptomatologia debutează de obicei tardiv, la 5-6 zile de la puncție, și se ameliorează spontan."},{"id":"B","text":"Mobilitatea mandibulară este sever redusă prin organizarea hematomului și fibrozare."},{"id":"C","text":"Este întotdeauna asociat cu un proces supurativ ce necesită imediat drenaj chirurgical."},{"id":"D","text":"Durerea induce un spasm muscular, limitând deschiderea arcadelor dentare, iar simptomatologia tinde să se agraveze progresiv."},{"id":"E","text":"Trismusul are tendința să se accentueze treptat în absența tratamentului."}],"correct":["D","E"],"pages":[565],"source":"set-2"},{"id":"set2-0MPTA8pB","fingerprint":"72633234bdc885ff","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt măsurile terapeutice recomandate în faza acută a trismusului postanestezic?","options":[{"id":"A","text":"Aplicarea de prișnițe calde timp de 20 de minute la fiecare oră."},{"id":"B","text":"Imobilizarea completă a mandibulei pentru a preveni spasmul muscular."},{"id":"C","text":"Instituirea imediată a unui tratament cu antibiotice, indiferent de evoluție."},{"id":"D","text":"Mecanoterapie prin mișcări mandibulare timp de 5 minute, la fiecare 3-4 ore."},{"id":"E","text":"Administrarea de midazolam sau alte benzodiazepine dacă durerea nu cedează."}],"correct":["A","D","E"],"pages":[565],"source":"set-2"},{"id":"set2-Xpmj77HD","fingerprint":"85cf9845fcd66738","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Când trebuie luată în considerare posibilitatea unui proces supurativ în cazul unui pacient cu trismus postanestezic?","options":[{"id":"A","text":"Dacă pacientul raportează o senzație de fulgurație în timpul injectării."},{"id":"B","text":"Atunci când durerea și disfuncția nu se ameliorează în 48-72 de ore de la inițierea tratamentului specific."},{"id":"C","text":"La pacienții care primesc anestezie la spina Spix, deoarece riscul este maxim."},{"id":"D","text":"Imediat ce pacientul acuză o limitare minoră a mobilității mandibulare."},{"id":"E","text":"Dacă se observă o ameliorare a simptomatologiei în primele 48 de ore de tratament."}],"correct":["B"],"pages":[565],"source":"set-2"},{"id":"set2-EIvli645","fingerprint":"bf202174afdc290d","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este mecanismul principal prin care traumatizarea unui trunchi nervos cu acul poate conduce la parestezie persistentă?","options":[{"id":"A","text":"O reacție alergică localizată la nivelul tecii nervului."},{"id":"B","text":"Formarea unui hematom care întrerupe vascularizația nervului."},{"id":"C","text":"Creșterea presiunii asupra filetului nervos din cauza edemului post-traumatic."},{"id":"D","text":"Senzația de fulgurație resimțită de pacient în timpul injectării."},{"id":"E","text":"Acțiunea neurotoxică directă a soluției anestezice asupra axonilor."}],"correct":["C"],"pages":[565],"source":"set-2"},{"id":"set2-oWGaQkeN","fingerprint":"ba9dfe852c4945af","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce proces patologic conduce la faza cronică a trismusului, caracterizată prin constricție de mandibulă, în absența unui tratament adecvat?","options":[{"id":"A","text":"Menținerea unui spasm muscular cronic din cauza durerii persistente."},{"id":"B","text":"O infecție cronică la nivelul spațiului pterigomandibular."},{"id":"C","text":"Apariția paresteziei persistente a nervului alveolar inferior."},{"id":"D","text":"Degenerarea articulației temporo-mandibulare ca urmare a imobilității."},{"id":"E","text":"Organizarea unui hematom, urmată de fibrozare și contractură cicatricială."}],"correct":["E"],"pages":[565],"source":"set-2"},{"id":"set2-aKKsuHYT","fingerprint":"06ef0179d3177629","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este un mecanism patogenic prin care poate apărea parestezia ca și complicație a anesteziei loco-regionale?","options":[{"id":"A","text":"O reacție alergică la substanța anestezică."},{"id":"B","text":"Hemoragia în jurul tecii nervoase, care duce la creșterea presiunii exercitate asupra nervului."},{"id":"C","text":"Formarea unui cheag alveolar necorespunzător care comprimă terminațiile nervoase."},{"id":"D","text":"Ischemia osului alveolar cauzată de vasoconstrictorul din anestezic."},{"id":"E","text":"O reacție inflamatorie locală severă la materialele de sutură."}],"correct":["B"],"pages":[565,566],"source":"set-2"},{"id":"set2-HiKPr1it","fingerprint":"175dcaa0b810920a","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect caracteristicile paresteziei persistente?","options":[{"id":"A","text":"Afectarea nervului lingual poate determina tulburări ale sensibilității gustative."},{"id":"B","text":"Nervul alveolar inferior este cel mai frecvent interesat, urmat de nervul lingual."},{"id":"C","text":"Poate conduce la autotraumatisme, precum leziuni prin mușcare, termice sau chimice."},{"id":"D","text":"Majoritatea cazurilor se remit spontan, fără tratament, într-un interval de aproximativ opt săptămâni."},{"id":"E","text":"Devine permanentă în toate cazurile în care leziunile nervoase sunt moderate."}],"correct":["A","C","D"],"pages":[566],"source":"set-2"},{"id":"set2-XVDLG0HW","fingerprint":"3638b8cb3f77152f","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce include managementul terapeutic al paresteziei?","options":[{"id":"A","text":"Injectarea locală de corticosteroizi pentru a reduce inflamația."},{"id":"B","text":"Monitorizarea pacientului și administrarea de vitamina B₁₂."},{"id":"C","text":"Administrarea de antibiotice cu spectru larg pentru a preveni suprainfecția."},{"id":"D","text":"Intervenție chirurgicală imediată pentru decompresia nervului afectat."},{"id":"E","text":"Aplicarea de comprese reci și administrarea de antiinflamatoare nesteroidiene."}],"correct":["B"],"pages":[566],"source":"set-2"},{"id":"set2-chECNz6t","fingerprint":"77780346959e6759","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este principalul element incriminat în etiopatogenia alveolitei postextracționale?","options":[{"id":"A","text":"Traumatismul osos excesiv în timpul extracției dentare."},{"id":"B","text":"Antisepsia deficitară a câmpului operator."},{"id":"C","text":"Vasoconstrictorul conținut în substanța anestezică."},{"id":"D","text":"Prezența unei infecții preexistente la nivelul dintelui extras."},{"id":"E","text":"Injectarea anestezicului sub o presiune crescută."}],"correct":["C"],"pages":[566],"source":"set-2"},{"id":"set2-ONXWxjim","fingerprint":"fca0ce3c6f73859e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt mecanismele prin care vasoconstrictorul din anestezic contribuie la apariția alveolitei postextracționale?","options":[{"id":"A","text":"Stimulează un răspuns inflamator local exacerbat, care lizează prematur cheagul."},{"id":"B","text":"Favorizează necroza prin inducerea ischemiei țesuturilor locale, în special a osului alveolar."},{"id":"C","text":"Împiedică sângerarea normală, afectând formarea unui cheag alveolar bine organizat."},{"id":"D","text":"Determină o hemoragie excesivă în jurul tecii nervoase, ducând la parestezie."},{"id":"E","text":"Crește presiunea intraosoasă, ceea ce duce la expulzarea cheagului format."}],"correct":["B","C"],"pages":[566],"source":"set-2"},{"id":"set2-8YlhIEZU","fingerprint":"24b1b102fd46b70b","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt cauzele care pot declanșa senzația de durere în momentul introducerii acului sau al injectării soluției anestezice?","options":[{"id":"A","text":"Folosirea unor ace cu bizoul teșit care produc dilacerarea țesutului."},{"id":"B","text":"Utilizarea unei rate de injectare constante de 1 ml/minut."},{"id":"C","text":"Tamponarea soluției anestezice cu bicarbonat de sodiu."},{"id":"D","text":"Injectarea rapidă, sub presiune, a soluției anestezice în zone cu țesuturi inextensibile."},{"id":"E","text":"Păstrarea carpulelor în soluții pentru sterilizare care difuzează în interiorul acestora."}],"correct":["A","D","E"],"pages":[560],"source":"set-2"},{"id":"set2-4vnTx_3l","fingerprint":"29f2b913452aeff8","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt consecințele clinice și caracteristicile înțepării trunchiului nervos sau a tecii nervoase în timpul puncției anestezice?","options":[{"id":"A","text":"Apariția unei dureri fulgurante, locale sau iradiate în teritoriul de inervare."},{"id":"B","text":"Riscul declanșării unor procese de nevrită traumatică, în cazul anesteziilor tronculare periferice."},{"id":"C","text":"Senzația dureroasă este de scurtă durată și dispare odată cu instalarea anesteziei."},{"id":"D","text":"Instalarea anesteziei se produce lent, cu o durată scurtă de acțiune."},{"id":"E","text":"Instalarea prelungită a sensibilității reziduale după încetarea efectului anestezic din cauza pH-ului acid."}],"correct":["A","B","C"],"pages":[560],"source":"set-2"},{"id":"set2-JQU1VFjk","fingerprint":"151e48a13ffb5296","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect influența caracteristicilor soluțiilor anestezice asupra producerii accidentelor și complicațiilor locale?","options":[{"id":"A","text":"Soluțiile anestezice care conțin vasoconstrictor prezintă un pH puternic alcalin, în jur de 8."},{"id":"B","text":"Injectarea soluțiilor contaminate cu alcool poate determina instalarea unei parestezii tranzitorii."},{"id":"C","text":"Durerea indusă de pH-ul acid dispare lent și asociază frecvent sensibilitate reziduală."},{"id":"D","text":"Utilizarea soluțiilor contaminate prin depozitarea carpulelor în alcool poate conduce la trismus și edem postanestezic."},{"id":"E","text":"pH-ul soluțiilor anestezice simple se situează de obicei în jurul valorii de 5."}],"correct":["B","D","E"],"pages":[560],"source":"set-2"},{"id":"set2-YtAkM_t1","fingerprint":"bcde22186f1c0621","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele particularități definesc accidentul de distensie bruscă sau dilacerare a țesuturilor în cursul anesteziei loco-regionale?","options":[{"id":"A","text":"Apare ca o consecință a injectării soluției anestezice sub presiune sau a introducerii unui volum excesiv."},{"id":"B","text":"Se asociază în mod constant cu instalarea rapidă și prelungită a efectului anestezic, de până la 5-6 ore."},{"id":"C","text":"Se produce cel mai frecvent în regiuni anatomice inextensibile, cum ar fi fibromucoasa palatină sau gingivomucoasa alveolară fixă."},{"id":"D","text":"Se manifestă clinic prin episoade de durere fulgurantă iradiată în dinții aferenți teritoriului de inervare."},{"id":"E","text":"Se previne prin asigurarea unei rate lente de injectare, ideală fiind valoarea de 1 ml/minut."}],"correct":["A","C","E"],"pages":[560],"source":"set-2"},{"id":"set2-Ytfr9dCq","fingerprint":"44e4115a5d257476","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este intervenția procedurală recomandată pentru atenuarea senzației dureroase cauzate exclusiv de pH-ul acid al soluției anestezice?","options":[{"id":"A","text":"Încălzirea soluției anestezice la o temperatură semnificativ superioară celei ambientale anterior injectării."},{"id":"B","text":"Reducerea ratei de injectare la o valoare fixă de 2 ml/minut."},{"id":"C","text":"Tamponarea soluției anestezice cu o substanță alcalinizantă, cum ar fi bicarbonatul de sodiu."},{"id":"D","text":"Administrarea predilectă a soluțiilor anestezice care conțin agenți vasoconstrictori."},{"id":"E","text":"Utilizarea carpulelor depozitate în soluții de sterilizare cu conținut alcoolic scăzut."}],"correct":["C"],"pages":[560],"source":"set-2"},{"id":"set2-J2wIPqS2","fingerprint":"d6e34445739170bd","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt consecințele creșterii acidității și ale prezenței inflamației asupra acțiunii anestezicului local?","options":[{"id":"A","text":"Întârzierea instalării anesteziei și posibila afectare a profunzimii acesteia."},{"id":"B","text":"Absorbția mai lentă a anestezicului din cauza vasoconstricției inflamatorii regionale."},{"id":"C","text":"Blocarea canalelor de sodiu exclusiv de către forma neionizată a substanței anestezice."},{"id":"D","text":"Creșterea proporției de bază neionizată la nivelul țesutului extracelular."},{"id":"E","text":"Creșterea conductibilității nervoase prin scăderea pragului de răspuns nervos."}],"correct":["A","E"],"pages":[561,562],"source":"set-2"},{"id":"set2-HmYHiVt5","fingerprint":"8477c2912ac796fc","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt metodele descrise pentru obținerea unei anestezii eficiente în prezența inflamației tisulare?","options":[{"id":"A","text":"Injectarea anestezicului sub presiune maximă direct în țesutul inflamat."},{"id":"B","text":"Efectuarea unei anestezii tronculare periferice la distanță de zona de inflamație."},{"id":"C","text":"Utilizarea unei cantități minime de anestezic pentru a evita diluarea acestuia în exudatul inflamator."},{"id":"D","text":"Injectarea unor cantități mai mari de anestezic printr-o anestezie în baraj."},{"id":"E","text":"Administrarea prealabilă a acidului clorhidric pentru creșterea pH-ului local."}],"correct":["B","D"],"pages":[561,562],"source":"set-2"},{"id":"set2-g0Qca6cd","fingerprint":"bf3be471628fdc41","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt implicațiile și atitudinea terapeutică recomandate în cazul puncționării unui vas de sânge în cursul anesteziilor tronculare periferice?","options":[{"id":"A","text":"Prezența unei cantități mari de sânge în seringă impune schimbarea seringii și a soluției anestezice."},{"id":"B","text":"Pătrunderea hemoglobinei în seringa anestezică determină inactivarea substanței active."},{"id":"C","text":"Perforarea unei vene este urmată constant și obligatoriu de apariția unui hematom masiv."},{"id":"D","text":"Aspirarea obligatorie trebuie efectuată înainte de a injecta soluția anestezică."},{"id":"E","text":"Injectarea intravasculară accidentală accelerează și prelungește efectul anestezic în teritoriul vizat."}],"correct":["A","B","D"],"pages":[561,562],"source":"set-2"},{"id":"set2-UZqY-uP4","fingerprint":"a4244219f8f6385f","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele etape descriu corect mecanismul de acțiune al anestezicelor locale injectabile în țesuturile sănătoase?","options":[{"id":"A","text":"Forma cationică extracelulară pătrunde cu ușurință prin membrana fibrei nervoase."},{"id":"B","text":"Baza neionizată rezultată în urma neutralizării este forma care difuzează prin teaca nervoasă."},{"id":"C","text":"Forma cationică intracelulară este responsabilă pentru blocarea canalelor de sodiu."},{"id":"D","text":"Baza neionizată pătrunsă în nerv întâlnește un pH normal și se transformă integral într-o nouă moleculă stabilă de bază neionizată."},{"id":"E","text":"Anestezicele locale sunt injectate sub formă de sare și sunt neutralizate de sistemele tampon din fluidul tisular."}],"correct":["B","C","E"],"pages":[561,562],"source":"set-2"},{"id":"set2-zuq3jPLN","fingerprint":"eb6b3486963c3980","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"De ce este contraindicată injectarea soluțiilor anestezice direct în zonele de inflamație sau infecție?","options":[{"id":"A","text":"Anestezicul provoacă necroză tisulară severă datorită interacțiunii directe cu exudatul inflamator."},{"id":"B","text":"Cantitatea mare de baze neionizate formate în țesutul inflamat devine toxică pentru fibrele nervoase motorii."},{"id":"C","text":"Soluțiile anestezice inactivează sistemele tampon locale, distrugând mecanismele de apărare celulară."},{"id":"D","text":"Creșterea bruscă a pH-ului tisular induce precipitarea anestezicului sub formă de cristale."},{"id":"E","text":"Există riscul extinderii infecției către zonele anatomice neimplicate anterior."}],"correct":["E"],"pages":[561,562],"source":"set-2"},{"id":"set2-JZip1-PC","fingerprint":"01d07ababf51d80f","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la fiziopatologia și factorii de risc implicați în formarea hematomului post-anestezic?","options":[{"id":"A","text":"Procesul de extravazare sanguină poate fi oprit prin formarea locală a cheagului."},{"id":"B","text":"Un hematom voluminos apare mai frecvent în urma lezării vasculare din cursul anesteziei tronculare periferice la tuberozitate."},{"id":"C","text":"Densitatea țesuturilor care înconjoară vasul lezat reprezintă un factor determinant în apariția hematomului."},{"id":"D","text":"Anestezia la nivelul bolții palatine se asociază frecvent cu formarea hematoamelor din cauza laxității tisulare accentuate."},{"id":"E","text":"Extravazarea sanguină continuă până când presiunea intravasculară o depășește pe cea extravasculară."}],"correct":["A","B","C"],"pages":[562],"source":"set-2"},{"id":"set2-eeFtebao","fingerprint":"561141f89c90371c","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele structuri vasculare pot fi lezate prin înțepare în timpul anesteziei la tuberozitate, generând un hematom al obrazului?","options":[{"id":"A","text":"Vena retromandibulară."},{"id":"B","text":"Artera alveolară postero-superioară."},{"id":"C","text":"Artera maxilară internă."},{"id":"D","text":"Plexul venos pterigoidian."},{"id":"E","text":"Artera facială."}],"correct":["B","C","D"],"pages":[562],"source":"set-2"},{"id":"set2-ielPr_h6","fingerprint":"3f5475e47e57d75a","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt elementele ce definesc conduita terapeutică corectă în cazul hematomului apărut după anestezia la tuberozitate?","options":[{"id":"A","text":"Se introduce un rulou de comprese în șanțul vestibular superior, poziționat cât mai anterior posibil."},{"id":"B","text":"Se aplică un prișnitz rece fixat cu un pansament compresiv, menținut pentru o perioadă de 24-48 de ore."},{"id":"C","text":"Se realizează imediat compresia regiunii geniene cu palma, menținută timp de câteva minute."},{"id":"D","text":"Se utilizează căldura locală în primele șase ore postincident pentru a grăbi procesul de resorbție."},{"id":"E","text":"După 48 de ore, se aplică un prișnitz cald timp de 20 de minute, la interval de o oră."}],"correct":["B","C","E"],"pages":[562],"source":"set-2"},{"id":"set2-sKJ7hbV4","fingerprint":"4a98d450a7df640e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce caracteristici definesc tabloul clinic și opțiunile terapeutice ale hematomului apărut după anestezia la spina Spix?","options":[{"id":"A","text":"Tumefacția se localizează pe fața internă a ramului mandibular, fiind asociată uneori cu modificarea de culoare a mucoasei."},{"id":"B","text":"Măsurile terapeutice exclud administrarea de antibiotice, indiferent de volumul hematomului."},{"id":"C","text":"Manifestările clinice sunt de regulă exorale, caracterizate printr-o tumefacție geniană difuză."},{"id":"D","text":"Presiunea terapeutică se exercită obligatoriu pe fața externă a ramului mandibular."},{"id":"E","text":"Acumularea sângelui are loc cu predilecție în fosa infratemporală, favorizând extinderea inferioară masivă."}],"correct":["A"],"pages":[562],"source":"set-2"},{"id":"set2-0KWlV4Wl","fingerprint":"5a9af286dc7bbad6","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Ce trăsătură descrie evoluția generală a hematomului post-anestezic și abordarea pacienților afectați?","options":[{"id":"A","text":"Utilizarea căldurii locale după 48 de ore determină un efect vasoconstrictor puternic, încetinind rata de resorbție."},{"id":"B","text":"Cu sau fără tratament medical, hematomul se resoarbe de obicei într-o perioadă de 7-10 zile."},{"id":"C","text":"Tratamentele stomatologice de necesitate pot fi reluate la 24 de ore postincident, în prezența pansamentului compresiv."},{"id":"D","text":"Resorbția spontană a hematomului necesită întotdeauna un interval minim de 14 până la 21 de zile."},{"id":"E","text":"Prescrierea de antibiotice este strict contraindicată deoarece hematomul nu prezintă risc de suprainfectare."}],"correct":["B"],"pages":[562],"source":"set-2"},{"id":"set2-Wujv2CT9","fingerprint":"9bdb6496a837d291","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt semnele clinice caracteristice parezei faciale tranzitorii, apărute ca accident în timpul anesteziei la spina Spix?","options":[{"id":"A","text":"Oftalmoplegia"},{"id":"B","text":"Asimetria facială"},{"id":"C","text":"Dispariția mișcărilor mimicii de partea opusă afectării"},{"id":"D","text":"Coborârea comisurii bucale"},{"id":"E","text":"Exoftalmia"}],"correct":["B","D","E"],"pages":[562],"source":"set-2"},{"id":"set2-z7SG2dU6","fingerprint":"c3574825bdada8d6","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt factorii favorizanți implicați în producerea ruperii acului în timpul anesteziei loco-regionale?","options":[{"id":"A","text":"Introducerea completă a acului până la ambou"},{"id":"B","text":"Introducerea rapidă a acului prin țesuturi și lovirea de planul osos"},{"id":"C","text":"Utilizarea unor ace care au fost îndoite anterior"},{"id":"D","text":"Schimbarea lentă și progresivă a direcției acului intratisular"},{"id":"E","text":"Utilizarea unor ace cu rezistență crescută la rupere"}],"correct":["A","B","C"],"pages":[563],"source":"set-2"},{"id":"set2-mk06BVOD","fingerprint":"c49591ce8111c42e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care afirmație este valabilă referitor la anestezia tranzitorie a nervului auriculo-temporal apărută în cursul anesteziei la spina Spix?","options":[{"id":"A","text":"Apare ca urmare a introducerii acului mult mai sus."},{"id":"B","text":"Se asociază cu o ischemie tranzitorie la nivelul nervului facial, prelungind tulburările motorii."},{"id":"C","text":"Se produce atunci când injectarea se realizează prea profund, direcționând acul spre posterior."},{"id":"D","text":"Determină anestezia zonei infraorbitare și a aripioarei nazale."},{"id":"E","text":"Reprezintă cauza principală a diplopiei și oftalmoplegiei tranzitorii."}],"correct":["A"],"pages":[563],"source":"set-2"},{"id":"set2-E5a-2Fxg","fingerprint":"9be7995c57ee2e38","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Ce manifestări clinice apar atunci când acul pătrunde accidental în orbită și înțeapă țesuturile perioculare sau globul ocular în timpul anesteziei nervului infraorbitar?","options":[{"id":"A","text":"Coborârea comisurii bucale cu asimetrie facială"},{"id":"B","text":"Exoftalmie tranzitorie cu remisie în 1-1,5 ore fără tratament"},{"id":"C","text":"Echimoze conjunctivo-bulbare"},{"id":"D","text":"Tulburări persistente de vedere"},{"id":"E","text":"Hemoragii sau hematoame intraorbitare sau intraoculare"}],"correct":["C","D","E"],"pages":[563],"source":"set-2"},{"id":"set2-vfnA6m6s","fingerprint":"4278a3c5a492b20e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care este atitudinea terapeutică adecvată în cazul în care acul s-a rupt în țesuturi pe parcursul anesteziei loco-regionale?","options":[{"id":"A","text":"Temporizarea intervenției chirurgicale oro-maxilo-faciale până la vindecarea plăgii mucozale."},{"id":"B","text":"Solicitarea pacientului de a efectua mișcări repetate de deschidere a cavității bucale pentru exteriorizarea acului."},{"id":"C","text":"Prinderea capătului rupt al acului cu o pensă Pean și îndepărtarea acestuia, atunci când este vizibil în cavitatea orală."},{"id":"D","text":"Localizarea precisă a poziției acului prin examen radiologic în situația acoperirii complete a acestuia."},{"id":"E","text":"Evitarea oricărei manopere dacă acul este acoperit complet în țesuturi."}],"correct":["C","D","E"],"pages":[563],"source":"set-2"},{"id":"set2-gh-PbvWw","fingerprint":"b81c5ab382d82eb6","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt afirmațiile adevărate privind necroza mucoasei apărută ca o complicație a anesteziei loco-regionale?","options":[{"id":"A","text":"Conduce la formarea de flictene care se deschid spontan, urmate uneori de eliminarea de mici sechestre osoase."},{"id":"B","text":"Se suprainfectează frecvent, scurtând perioada de vindecare."},{"id":"C","text":"Leziunea are o evoluție clinică de aproximativ 7-10 zile."},{"id":"D","text":"Apare mai frecvent la nivelul mucoasei vestibulare, comparativ cu bolta palatină."},{"id":"E","text":"Este cauzată în principal de ischemia prelungită determinată de vasoconstrictorul din soluția anestezică."}],"correct":["A","C","E"],"pages":[564],"source":"set-2"},{"id":"set2-HAed0v1A","fingerprint":"50c7ae944e93a40e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este conduita terapeutică și evoluția ulcerațiilor mucoasei apărute consecutiv anesteziei loco-regionale?","options":[{"id":"A","text":"Prevenirea acestor leziuni se realizează prin aplicarea profilactică a antiviralelor la pacienții susceptibili."},{"id":"B","text":"Vindecarea este rapidă, leziunile remițându-se spontan în 1-2 zile fără intervenție terapeutică."},{"id":"C","text":"Complicația are etiologie exclusiv bacteriană, necesitând antibioterapie sistemică de urgență."},{"id":"D","text":"Este recomandată asocierea unui corticosteroid pentru a reduce inflamația și a preveni suprainfectarea."},{"id":"E","text":"Irigațiile locale utilizate pot conține o asociere între un antihistaminic, un antiinflamator și un analgezic local."}],"correct":["E"],"pages":[563],"source":"set-2"},{"id":"set2-vU6IENq5","fingerprint":"42cc594330bcc920","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt caracteristicile clinice și fiziopatologice ale injectitelor postanestezice?","options":[{"id":"A","text":"Simptomatologia debutează de obicei la 2-3 zile de la puncția anestezică."},{"id":"B","text":"Durerile prezente au un caracter nevralgiform iradiat și nu cedează la antialgicele obișnuite."},{"id":"C","text":"Apar exclusiv pe fondul decolării brutale a mucoperiostului în timpul puncției anestezice."},{"id":"D","text":"Dezvoltarea procesului septic este favorizată de prezența abundentă a țesutului celulo-adipos și a hematoamelor."},{"id":"E","text":"Manifestările clinice au o latență mai mică atunci când procesul septic interesează spațiile profunde."}],"correct":["A","B","D"],"pages":[564],"source":"set-2"},{"id":"set2-r8BtTioN","fingerprint":"bce864816133f4e1","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următorii factori și caracteristici sunt asociați cu etiologia ulcerațiilor mucoasei apărute postanestezic?","options":[{"id":"A","text":"Traumatismele tisulare produse de ac sau de soluția anestezică pot activa forma latentă a stomatitei aftoase recidivante."},{"id":"B","text":"Herpesul simplex are etiologie virală și debutează inițial sub forma unor mici vezicule pe mucoasa fixă."},{"id":"C","text":"Nu există nicio metodă de prevenire a acestor leziuni orale la pacienții susceptibili."},{"id":"D","text":"Stomatita aftoasă recidivantă apare cu predilecție la nivelul mucoasei fixe a bolții palatine."},{"id":"E","text":"Stomatita aftoasă recidivantă este considerată o afecțiune de etiologie strict fungică."}],"correct":["A","B","C"],"pages":[564],"source":"set-2"},{"id":"set2-pUi9DKJT","fingerprint":"e577ace13d049be8","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este măsura recomandată pentru prevenirea descuamării epiteliale consecutive aplicării anestezicului topic?","options":[{"id":"A","text":"Utilizarea profilactică a unei plăci palatinale acrilice înainte de injectare."},{"id":"B","text":"Evitarea utilizării de soluții anestezice care conțin concentrații mari de vasoconstrictor."},{"id":"C","text":"Menținerea anestezicului topic în contact cu mucoasa numai pentru 1-2 minute."},{"id":"D","text":"Aplicarea imediată a unor meșe iodoformate pentru a proteja procesul de epitelizare secundară."},{"id":"E","text":"Menținerea anestezicului topic în contact cu mucoasa pentru o perioadă de minimum 5-7 minute."}],"correct":["C"],"pages":[563],"source":"set-2"},{"id":"set2-OCFixEkn","fingerprint":"6b8074c6203df6b4","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următorii factori sunt incriminați în etiologia trismusului persistent postanestezic?","options":[{"id":"A","text":"Iritația tisulară și disfuncția musculară secundare hemoragiei cu acumularea unor cantități mari de sânge."},{"id":"B","text":"Ischemia prelungită determinată de prezența vasoconstrictorului în soluția anestezică."},{"id":"C","text":"Distensia tisulară produsă de injectarea unor cantități reduse de anestezic pe o arie extinsă."},{"id":"D","text":"Însămânțarea spațiului pterigomandibular printr-o puncție septică."},{"id":"E","text":"Traumatismul tisular secundar puncțiilor anestezice repetate."}],"correct":["A","B","D","E"],"pages":[565],"source":"set-2"},{"id":"set2-X4ajaB4L","fingerprint":"592e0c84f7db8e2c","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este mecanismul principal de dezvoltare a fazei tardive sau cronice a trismusului postanestezic în absența terapiei adecvate?","options":[{"id":"A","text":"Hipertrofia compensatorie a mușchiului maseter pe partea controlaterală."},{"id":"B","text":"Instalarea imediată a unui proces supurativ difuz la nivelul spațiului submandibular."},{"id":"C","text":"Osificarea progresivă a ligamentului sfenomandibular."},{"id":"D","text":"Apariția unei pareze tranzitorii a nervului facial secundară puncției profunde."},{"id":"E","text":"Organizarea hematomului cu fibrozare ulterioară și contractură cicatricială."}],"correct":["E"],"pages":[565],"source":"set-2"},{"id":"set2-JOc6MRWx","fingerprint":"905d95a6d7acb1ef","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt măsurile terapeutice recomandate în managementul fazei acute a trismusului postanestezic?","options":[{"id":"A","text":"Administrarea de midazolam sau alte benzodiazepine pentru relaxarea musculară, în cazul în care durerea nu cedează."},{"id":"B","text":"Aplicarea de prișnițe reci pentru 20 de minute la fiecare oră."},{"id":"C","text":"Imobilizarea completă a mandibulei pentru o perioadă de 48 de ore."},{"id":"D","text":"Efectuarea mecanoterapiei prin mișcări de deschidere, închidere și lateralitate timp de 5 minute la fiecare 3-4 ore."},{"id":"E","text":"Administrarea de analgezice."}],"correct":["A","D","E"],"pages":[565],"source":"set-2"},{"id":"set2-fvAomx31","fingerprint":"1b263d3652e1ec06","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este atitudinea terapeutică indicată în situația în care durerea și disfuncția din trismusul postanestezic nu se ameliorează după 48-72 de ore de tratament conservator?","options":[{"id":"A","text":"Se efectuează o nouă puncție anestezică profundă cu un anestezic cu durată lungă de acțiune pentru a obține o blocare a fibrelor motorii."},{"id":"B","text":"Se inițiază un tratament exclusiv cu miorelaxante intravenoase din clasa benzodiazepinelor cu timp de înjumătățire lung."},{"id":"C","text":"Se suspectează un proces supurativ și se intervine prin incizie și drenaj sub protecție de antibiotice."},{"id":"D","text":"Se aplică imobilizare intermaxilară rigidă pentru a preveni extinderea spasmului și fibrozarea ulterioară."},{"id":"E","text":"Se recomandă continuarea mecanoterapiei cu creșterea duratei exercițiilor la 20 de minute pe oră."}],"correct":["C"],"pages":[565],"source":"set-2"},{"id":"set2-F-ejnq3Z","fingerprint":"47f9a7da9de2481e","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristicile clinice și evolutive ale trismusului postanestezic?","options":[{"id":"A","text":"Durerea din faza acută conduce la spasm muscular și implicit la limitarea deschiderii arcadelor dentare."},{"id":"B","text":"Trismusul are o tendință naturală de remisie spontană în primele zile de la debut, fără necesitatea unui tratament."},{"id":"C","text":"Este cel mai frecvent întâlnit după anestezia la spina Spix comparativ cu alte tipuri de anestezie tronculară periferică."},{"id":"D","text":"Simptomatologia se instalează exclusiv precoce, în primele 12 ore de la puncția anestezică."},{"id":"E","text":"Puncțiile repetate, cum sunt cele din tratamentul nevralgiei trigeminale, se asociază cu o incidență crescută a acestei afecțiuni."}],"correct":["A","C","E"],"pages":[565],"source":"set-2"},{"id":"set2-FDsE8O5W","fingerprint":"7b92471da202b27b","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următoarele reprezintă mecanisme etiopatogenice sau manifestări clinice ale paresteziilor persistente apărute în urma anesteziei loco-regionale?","options":[{"id":"A","text":"Lipsa sensibilității predispune pacientul la leziuni autotraumatice exclusiv de natură chimică."},{"id":"B","text":"Hemoragia în jurul tecii nervoase determină creșterea presiunii exercitate asupra nervului."},{"id":"C","text":"Edemul local conduce la scăderea presiunii în zona filetului nervos, generând parestezie."},{"id":"D","text":"Traumatizarea tecii nervului prin contactul cu acul produce o senzație de fulgurație în teritoriul de distribuție nervoasă."},{"id":"E","text":"Implicarea nervului lingual poate fi însoțită de afectarea sensibilității gustative."}],"correct":["B","D","E"],"pages":[565],"source":"set-2"},{"id":"set2-z6Nz4wBl","fingerprint":"7261c78cde0d2bf0","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care sunt afirmațiile adevărate privind evoluția, frecvența afectării nervoase și tratamentul paresteziilor persistente?","options":[{"id":"A","text":"Majoritatea paresteziilor persistente necesită tratament medicamentos complex pentru remitere în aproximativ opt săptămâni."},{"id":"B","text":"Cel mai frecvent afectat este nervul alveolar inferior, urmat ca frecvență de nervul lingual."},{"id":"C","text":"Abordarea terapeutică de bază presupune monitorizarea pacientului și administrarea de vitamina B₁₂."},{"id":"D","text":"Parestezia devine permanentă doar în situația în care leziunile nervoase sunt foarte severe."},{"id":"E","text":"În marea majoritate a situațiilor, parestezia este totală, cu pierderea completă a sensibilității în regiunea implicată."}],"correct":["C","D"],"pages":[566],"source":"set-2"},{"id":"set2-ZaF3xV7c","fingerprint":"66d6bf3a586e0f98","chapterId":"set-2","subchapterId":"set2-7.03","type":"CM","text":"Care dintre următorii factori sau mecanisme sunt implicați în instalarea alveolitei postextracționale în contextul anesteziei loco-regionale?","options":[{"id":"A","text":"Împiedicarea sângerării normale compromite formarea unui cheag alveolar bine organizat."},{"id":"B","text":"Anestezia intraligamentară prezintă un risc scăzut de alveolită postextracțională datorită injectării la presiune minimă."},{"id":"C","text":"Ischemia osului alveolar previne apariția proceselor de necroză tisulară."},{"id":"D","text":"Antisepsia deficitară a câmpului operator în anestezia intraligamentară contribuie la dezvoltarea alveolitei."},{"id":"E","text":"Vasoconstrictorul din substanța anestezică produce o vasoconstricție bruscă și uneori prelungită."}],"correct":["A","D","E"],"pages":[566],"source":"set-2"},{"id":"set2-0w6fqMql","fingerprint":"a95d086431d27fed","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care este nervul cel mai frecvent afectat de paresteziile persistente post-anestezice și ce abordare terapeutică se recomandă?","options":[{"id":"A","text":"Nervul alveolar inferior; intervenție chirurgicală imediată pentru decompresie."},{"id":"B","text":"Nervul alveolar inferior; monitorizare și administrare de vitamina B₁₂."},{"id":"C","text":"Nervul maxilar; monitorizare clinică pe o durată de maximum două săptămâni."},{"id":"D","text":"Nervul facial; administrare de analgezice puternice."},{"id":"E","text":"Nervul lingual; monitorizare și administrare de vitamina B₁₂."}],"correct":["E"],"pages":[566],"source":"set-2"},{"id":"set2-vIsm6_OZ","fingerprint":"55a28eba9e8d8968","chapterId":"set-2","subchapterId":"set2-7.03","type":"CS","text":"Care dintre următoarele mecanisme este responsabil pentru generarea unei parestezii ce poate persista luni sau ani de zile după o anestezie loco-regională?","options":[{"id":"A","text":"Creșterea presiunii în zona filetului nervos din cauza edemului apărut în urma traumatizării trunchiurilor nervoase cu acul."},{"id":"B","text":"Vasodilatația excesivă care scade brusc presiunea în zona filetului nervos."},{"id":"C","text":"Ischemia țesuturilor locale indusă de vasoconstrictorul din substanța anestezică."},{"id":"D","text":"Antisepsia deficitară a câmpului operator care induce modificări chimice ale tecii nervoase."},{"id":"E","text":"Formarea unui cheag alveolar ineficient din cauza sângerării deficitare."}],"correct":["A"],"pages":[565],"source":"set-2"}];
